long long key_number(long long n) {
    long long largest = 0;
    long long sum_others = 0;
    long long temp = n;

    // Factor out 2
    int count = 0;
    while (temp % 2 == 0) {
        temp /= 2;
        count++;
    }
    if (count > 0) {
        largest = 2;
        // If more than one factor of 2, 2 is not the only prime factor
        // but sum_others will include 2 only once if there are other primes
        // Actually we treat each distinct prime factor once.
    }

    // Check odd factors up to sqrt(temp)
    for (long long i = 3; i * i <= temp; i += 2) {
        count = 0;
        while (temp % i == 0) {
            temp /= i;
            count++;
        }
        if (count > 0) {
            if (i > largest) {
                if (largest != 0)
                    sum_others += largest;
                largest = i;
            } else {
                sum_others += i;
            }
        }
    }

    // If temp is a prime greater than 2
    if (temp > 1) {
        if (temp > largest) {
            if (largest != 0)
                sum_others += largest;
            largest = temp;
        } else {
            sum_others += temp;
        }
    }

    return largest - sum_others;
}

