// Returns key number of n
// key = largest_prime_factor - sum_of_all_other_prime_factors
long long key_number(long long n) {
    // Get all prime factors with multiplicity
    long long factors[1000];
    int count = 0;

    for (long long i = 2; i * i <= n; i++) {
        while (n % i == 0) {
            factors[count++] = i;
            n /= i;
        }
    }
    if (n > 1) {
        factors[count++] = n;
    }

    if (count == 0) return 0; // n = 1, no prime factors

    // Find largest
    long long largest = factors[0];
    int largest_idx = 0;
    for (int i = 1; i < count; i++) {
        if (factors[i] > largest) {
            largest = factors[i];
            largest_idx = i;
        }
    }

    // Sum of all others
    long long sum_others = 0;
    for (int i = 0; i < count; i++) {
        if (i != largest_idx) {
            sum_others += factors[i];
        }
    }

    return largest - sum_others;
}

