long long key_number(long long n) {
    long long original = n;
    long long sum_other = 0;
    long long largest = 0;

    while (n % 2 == 0) {
        sum_other += 2;
        largest = 2;
        n /= 2;
    }

    for (long long p = 3; p * p <= n; p += 2) {
        while (n % p == 0) {
            sum_other += p;
            largest = p;
            n /= p;
        }
    }

    if (n > 1) {
        sum_other += n;
        largest = n;
    }

    /* remove one occurrence of the largest prime factor from the total sum */
    return largest - (sum_other - largest);
}

