import sys

def sieve_spf(limit):
    spf = list(range(limit + 1))
    for i in range(2, int(limit**0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, limit + 1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf

def prime_factors(n, spf):
    factors = []
    while n > 1:
        p = spf[n]
        factors.append(p)
        while n % p == 0:
            n //= p
    return factors

def key_number(n, spf):
    factors = prime_factors(n, spf)
    if not factors:
        return 0
    largest = max(factors)
    others_sum = sum(factors) - largest
    return largest - others_sum

