def prime_factors_with_multiplicity(n: int):
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    d = 3
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 2
    if n > 1:
        factors.append(n)
    return factors

def key_number(n: int) -> int:
    factors = prime_factors_with_multiplicity(n)
    largest = max(factors)
    return largest - (sum(factors) - largest)

