        long temp = n;
        long largest = 0;
        long sumOthers = 0;

        for (long p = 2; p * p <= temp; p += (p == 2 ? 1 : 2)) {
            while (temp % p == 0) {
                if (p > largest) {
                    if (largest != 0) sumOthers += largest;
                    largest = p;
                } else {
                    sumOthers += p;
                }
                temp /= p;
            }
        }

        if (temp > 1) {
            long p = temp;
            if (p > largest) {
                if (largest != 0) sumOthers += largest;
                largest = p;
            } else {
                sumOthers += p;
            }
        }

        return largest - sumOthers;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            Long a = fs.nextLongOrNull();
            if (a == null) break;
            long b = fs.nextLong();

            long ka = keyNumber(a);
            long kb = keyNumber(b);

            out.append(ka > kb ? 'a' : 'b').append('\n');
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        Long nextLongOrNull() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        long nextLong() throws IOException {
            return nextLongOrNull();
        }
    }
